<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import PageHeader from '../../components/PageHeader.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import { formatDateTime, statusLabel as commonStatusLabel } from '../../utils/display'
import { operationsApi, type AlertItem, type FailureItem, type OperationInstance, type OperationSummary, type OperationTask, type SystemMetrics } from '../../api/domain'

const route=useRoute(),router=useRouter()
const loading=ref(true),summary=ref<OperationSummary|null>(null),tasks=ref<OperationTask[]>([]),instances=ref<OperationInstance[]>([]),failures=ref<FailureItem[]>([]),alerts=ref<AlertItem[]>([]),systemMetrics=ref<SystemMetrics|null>(null)
const taskType=ref('ALL'),keyword=ref(''),busy=ref(new Set<string>()),detailOpen=ref(false),detail=ref<OperationTask>(),logOpen=ref(false),logTitle=ref('运行日志'),logText=ref('')
const mode=computed(()=>route.path.split('/').pop()||'overview')
const title=computed(()=>({overview:'运维总览',tasks:'任务运维',instances:'运行实例',failures:'失败任务',alerts:'告警中心'} as Record<string,string>)[mode.value]||'运维中心')
const subtitle=computed(()=>({overview:'统一监控离线集成、实时集成和数据开发任务。',tasks:'只提供生产运维操作，不允许在运维中心修改任务配置。',instances:'查看三类任务的实际运行实例。',failures:'集中查看需要人工处理的失败任务。',alerts:'展示已经真实推送到告警渠道的历史记录。'} as Record<string,string>)[mode.value]||'')
const range=ref<'24h'|'7d'|'30d'>('24h')
const showSuccess=ref(true),showFailed=ref(true),showRunning=ref(true),hoverIndex=ref<number|null>(null)
const rangeOptions=[{key:'24h',label:'近24小时'},{key:'7d',label:'近7日'},{key:'30d',label:'近30日'}] as const
const filteredTasks=computed(()=>tasks.value.filter(x=>(taskType.value==='ALL'||x.type===taskType.value)&&(!keyword.value.trim()||x.name.toLowerCase().includes(keyword.value.trim().toLowerCase()))))
const successStatus=(v?:string)=>/SUCCESS|FINISHED|COMPLETED/i.test(v||'')
const failedStatus=(v?:string)=>/FAILED|ERROR/i.test(v||'')
const runningStatus=(v?:string)=>/RUNNING|STARTING|QUEUED|SUBMITTED/i.test(v||'')
function instanceTime(r:OperationInstance){const raw=r.finishedAt||r.startedAt||r.createdAt;return raw?new Date(raw):null}
function bucketStart(d:Date,kind:'hour'|'day'){const x=new Date(d);if(kind==='hour'){x.setMinutes(0,0,0)}else{x.setHours(0,0,0,0)}return x}
function bucketLabel(d:Date,kind:'hour'|'day'){return kind==='hour'?`${String(d.getHours()).padStart(2,'0')}:00`:`${d.getMonth()+1}/${d.getDate()}`}
const trendData=computed(()=>{
  const now=new Date();const hourly=range.value==='24h';const count=hourly?24:range.value==='7d'?7:30;const kind:'hour'|'day'=hourly?'hour':'day';
  const end=bucketStart(now,kind);const step=hourly?3600000:86400000;const starts=Array.from({length:count},(_,i)=>new Date(end.getTime()-(count-1-i)*step));
  const rows=starts.map(d=>({time:d,label:bucketLabel(d,kind),success:0,failed:0,running:0}));const startAt=starts[0]?.getTime()??0;const endAt=end.getTime()+step;
  for(const item of instances.value){const t=instanceTime(item)?.getTime();if(!t||t<startAt||t>=endAt)continue;const idx=Math.floor((bucketStart(new Date(t),kind).getTime()-startAt)/step);if(idx<0||idx>=rows.length)continue;if(successStatus(item.status))rows[idx].success+=1;else if(failedStatus(item.status))rows[idx].failed+=1;else if(runningStatus(item.status))rows[idx].running+=1}
  const success=rows.reduce((n,x)=>n+x.success,0),failed=rows.reduce((n,x)=>n+x.failed,0),running=rows.reduce((n,x)=>n+x.running,0);const yMax=Math.max(1,...rows.flatMap(x=>[x.success,x.failed,x.running]));return{rows,success,failed,running,total:success+failed+running,yMax}
})
function chartPoint(index:number,value:number){const w=720,h=228,left=42,right=18,top=18,bottom=34;const innerW=w-left-right,innerH=h-top-bottom;const n=Math.max(1,trendData.value.rows.length-1);return{x:left+(index/n)*innerW,y:top+(1-value/trendData.value.yMax)*innerH}}
function seriesPoints(type:'success'|'failed'|'running'){return trendData.value.rows.map((r,i)=>chartPoint(i,r[type]))}
function smoothPath(points:Array<{x:number;y:number}>){if(!points.length)return'';if(points.length===1)return`M ${points[0].x} ${points[0].y}`;let d=`M ${points[0].x.toFixed(1)} ${points[0].y.toFixed(1)}`;for(let i=0;i<points.length-1;i++){const p1=points[i],p2=points[i+1],mid=(p1.x+p2.x)/2;d+=` C ${mid.toFixed(1)} ${p1.y.toFixed(1)}, ${mid.toFixed(1)} ${p2.y.toFixed(1)}, ${p2.x.toFixed(1)} ${p2.y.toFixed(1)}`}return d}
function onTrendMove(event:MouseEvent){const el=event.currentTarget as SVGElement;const rect=el.getBoundingClientRect();if(!rect.width||!trendData.value.rows.length)return;const x=(event.clientX-rect.left)/rect.width*720;const n=Math.max(1,trendData.value.rows.length-1);hoverIndex.value=Math.max(0,Math.min(trendData.value.rows.length-1,Math.round((x-42)/660*n)))}
const hoverRow=computed(()=>hoverIndex.value==null?null:trendData.value.rows[hoverIndex.value])
const hoverPoint=computed(()=>hoverIndex.value==null?null:chartPoint(hoverIndex.value,0))
const successPath=computed(()=>smoothPath(seriesPoints('success')))
const failedPath=computed(()=>smoothPath(seriesPoints('failed')))
const runningPath=computed(()=>smoothPath(seriesPoints('running')))
const pieSuccessDeg=computed(()=>trendData.value.total?trendData.value.success/trendData.value.total*360:0)
function showXAxisLabel(i:number){const n=trendData.value.rows.length;if(n<=7)return true;if(n<=24)return i%4===0||i===n-1;return i%5===0||i===n-1}
const todayLabel=computed(()=>{const d=new Date();return `今日 ${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`})
const recentAlerts=computed(()=>[...alerts.value].sort((a,b)=>new Date(b.occurredAt||0).getTime()-new Date(a.occurredAt||0).getTime()).slice(0,5))
const componentCards=computed(()=>[
  {type:'OFFLINE',name:'离线集成',engine:'SeaTunnel'},
  {type:'REALTIME',name:'实时集成',engine:'Flink CDC'},
  {type:'DEVELOPMENT',name:'数据开发',engine:'StarRocks'}
].map(c=>{const rows=tasks.value.filter(x=>x.type===c.type);return{...c,total:rows.length,running:rows.filter(x=>runningStatus(x.runtimeStatus)).length,failed:rows.filter(x=>failedStatus(x.runtimeStatus)).length}}))
const allComponentsHealthy=computed(()=>componentCards.value.every(x=>x.failed===0))
function alertLevel(row:AlertItem){const text=`${row.status||''} ${row.message||''}`;if(/FAIL|ERROR|FATAL|CRITICAL/i.test(text))return{label:'严重',cls:'critical'};if(/WARN|TIMEOUT|DELAY|LAG|SLOW/i.test(text))return{label:'警告',cls:'warning'};return{label:'提示',cls:'info'}}
function formatBytes(value?:number){const n=Math.max(0,Number(value||0));if(n<1024)return`${n} B`;const units=['KB','MB','GB','TB'];let v=n/1024,i=0;while(v>=1024&&i<units.length-1){v/=1024;i++}return`${v>=10?v.toFixed(1):v.toFixed(2)} ${units[i]}`}
async function refreshSystemMetrics(){if(mode.value!=='overview')return;try{systemMetrics.value=await operationsApi.systemMetrics()}catch{systemMetrics.value=null}}
function go(path:string){void router.push(path)}
const typeLabel=(v:string)=>({OFFLINE:'离线集成',REALTIME:'实时集成',DEVELOPMENT:'数据开发'} as Record<string,string>)[v]||v
const lifecycleLabel=(v?:string)=>({ONLINE:'已上线',OFFLINE:'已下线',PUBLISHED:'已发布',DRAFT:'草稿'} as Record<string,string>)[String(v||'').toUpperCase()]||v||'—'
const key=(action:string,row:OperationTask)=>`${action}-${row.type}-${row.id}`
const isBusy=(action:string,row:OperationTask)=>busy.value.has(key(action,row))
function setBusy(action:string,row:OperationTask,value:boolean){const n=new Set(busy.value);value?n.add(key(action,row)):n.delete(key(action,row));busy.value=n}
function fmt(v?:string){return formatDateTime(v)}
function statusLabel(v?:string){return commonStatusLabel(v)}

async function load(){loading.value=true;try{if(mode.value==='overview'){const [s,t,i,a,m]=await Promise.all([operationsApi.summary(),operationsApi.tasks(),operationsApi.instances(),operationsApi.alerts(),operationsApi.systemMetrics()]);summary.value=s;tasks.value=t;instances.value=i;alerts.value=a;systemMetrics.value=m}if(mode.value==='tasks')tasks.value=await operationsApi.tasks();if(mode.value==='instances')instances.value=await operationsApi.instances();if(mode.value==='failures')failures.value=await operationsApi.failures();if(mode.value==='alerts')alerts.value=await operationsApi.alerts()}catch(e){ElMessage.error(e instanceof Error?e.message:'运维数据加载失败')}finally{loading.value=false}}
async function taskAction(action:'start'|'rerun'|'kill',row:OperationTask){const names={start:'启动',rerun:'重跑',kill:'杀死'};const name=names[action];try{await ElMessageBox.confirm(`确认${name}任务“${row.name}”？${action==='kill'?'运行中的实例将被终止。':''}`,`${name}确认`,{type:action==='kill'?'error':'warning',confirmButtonText:`确认${name}`,cancelButtonText:'取消'});setBusy(action,row,true);if(action==='start')await operationsApi.startTask(row.type,row.id);else if(action==='rerun')await operationsApi.rerunTask(row.type,row.id);else await operationsApi.killTask(row.type,row.id);ElMessage.success(action==='kill'?'杀死操作已执行':`${name}请求已成功提交`);await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:`${name}失败`)}finally{setBusy(action,row,false)}}
async function showLog(row:OperationTask){try{logTitle.value=`${row.name} · 运行日志`;logText.value='正在加载日志...';logOpen.value=true;logText.value=await operationsApi.taskLog(row.type,row.id)}catch(e){logText.value=e instanceof Error?e.message:'日志加载失败'}}
function showDetail(row:OperationTask){detail.value=row;detailOpen.value=true}
async function stopInstance(r:OperationInstance){try{await ElMessageBox.confirm(`确认杀死“${r.name}”当前实例？`,'杀死确认',{type:'error',confirmButtonText:'确认杀死',cancelButtonText:'取消'});await operationsApi.stop(r.type,r.id);ElMessage.success('杀死请求已执行');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'杀死失败')}}
async function instanceLog(r:OperationInstance){try{logTitle.value=`${r.name} · 实例日志`;logText.value='正在加载日志...';logOpen.value=true;logText.value=await operationsApi.log(r.type,r.id)}catch(e){logText.value=e instanceof Error?e.message:'日志加载失败'}}
let metricsTimer:number|undefined
watch(()=>route.path,load);onMounted(()=>{void load();metricsTimer=window.setInterval(()=>void refreshSystemMetrics(),10000)});onUnmounted(()=>{if(metricsTimer)window.clearInterval(metricsTimer)})
</script>

<template><div class="ds-page" :class="{'overview-page':mode==='overview'}"><PageHeader :title="title" :subtitle="subtitle"><template v-if="mode==='overview'" #actions><div class="overview-actions"><span class="today-chip">▣ {{todayLabel}}</span><button class="refresh-btn" @click="load">↻ 刷新</button></div></template></PageHeader>
<el-skeleton v-if="loading" :rows="7" animated/>
<template v-else-if="mode==='overview'&&summary">
  <div class="overview-metrics">
    <div class="overview-metric"><span class="metric-icon primary">▣</span><div><label>生产任务</label><strong>{{summary.total}}</strong><small>当前生产任务总数</small></div></div>
    <div class="overview-metric"><span class="metric-icon success">▶</span><div><label>运行中</label><strong>{{summary.running}}</strong><small>正在执行的任务</small></div></div>
    <div class="overview-metric"><span class="metric-icon primary">✓</span><div><label>最近成功</label><strong>{{summary.success}}</strong><small>最近执行成功</small></div></div>
    <div class="overview-metric"><span class="metric-icon danger">!</span><div><label>最近失败</label><strong class="danger-value">{{summary.failed}}</strong><small>需要关注的失败</small></div></div>
  </div>

  <div class="overview-grid primary-grid">
    <section class="dashboard-card trend-card">
      <div class="dashboard-head"><strong>任务运行趋势</strong><div class="range-switch"><button v-for="item in rangeOptions" :key="item.key" :class="{active:range===item.key}" @click="range=item.key">{{item.label}}</button></div></div>
      <div class="trend-body"><div class="legend"><button :class="{muted:!showSuccess}" @click="showSuccess=!showSuccess"><i class="success-dot"></i>成功 {{trendData.success}}</button><button :class="{muted:!showFailed}" @click="showFailed=!showFailed"><i class="failed-dot"></i>失败 {{trendData.failed}}</button><button :class="{muted:!showRunning}" @click="showRunning=!showRunning"><i class="running-dot"></i>运行中 {{trendData.running}}</button></div>
        <div class="trend-canvas"><svg class="trend-chart" viewBox="0 0 720 228" preserveAspectRatio="none" @mousemove="onTrendMove" @mouseleave="hoverIndex=null"><g class="grid-lines"><line v-for="y in [18,62,106,150,194]" :key="y" x1="42" :y1="y" x2="702" :y2="y"/></g><path v-if="showSuccess" class="line success-line" :d="successPath"/><path v-if="showFailed" class="line failed-line" :d="failedPath"/><path v-if="showRunning" class="line running-line" :d="runningPath"/><line v-if="hoverPoint" class="hover-guide" :x1="hoverPoint.x" y1="18" :x2="hoverPoint.x" y2="194"/><g v-for="(r,i) in trendData.rows" :key="`${r.label}-${i}`"><circle v-if="showSuccess" class="point success-point" :cx="chartPoint(i,r.success).x" :cy="chartPoint(i,r.success).y" :r="hoverIndex===i?4:2.8"/><circle v-if="showFailed" class="point failed-point" :cx="chartPoint(i,r.failed).x" :cy="chartPoint(i,r.failed).y" :r="hoverIndex===i?4:2.8"/><circle v-if="showRunning" class="point running-point" :cx="chartPoint(i,r.running).x" :cy="chartPoint(i,r.running).y" :r="hoverIndex===i?4:2.8"/><text v-if="showXAxisLabel(i)" class="x-label" :x="chartPoint(i,0).x" y="220">{{r.label}}</text></g></svg><div v-if="hoverRow&&hoverPoint" class="trend-tooltip" :style="{left:`${Math.min(88,Math.max(12,hoverPoint.x/720*100))}%`}"><strong>{{hoverRow.label}}</strong><span v-if="showSuccess"><i class="success-dot"></i>成功 {{hoverRow.success}}</span><span v-if="showFailed"><i class="failed-dot"></i>失败 {{hoverRow.failed}}</span><span v-if="showRunning"><i class="running-dot"></i>运行中 {{hoverRow.running}}</span></div></div>
      </div>
    </section>
    <section class="dashboard-card alerts-card"><div class="dashboard-head"><strong>最近告警</strong><button class="more-link" @click="go('/operations/alerts')">更多 ›</button></div><div v-if="!recentAlerts.length" class="compact-empty">暂无告警记录</div><div v-else class="alert-list"><div v-for="row in recentAlerts" :key="`${row.resourceId}-${row.occurredAt}`" class="alert-row"><span :class="['alert-level',alertLevel(row).cls]"><i></i>{{alertLevel(row).label}}</span><span class="alert-time">{{fmt(row.occurredAt)}}</span><span class="alert-source">{{row.name||row.resourceType}}</span><span class="alert-message" :title="row.message">{{row.message||statusLabel(row.status)}}</span></div></div></section>
  </div>

  <div class="overview-grid secondary-grid">
    <section class="dashboard-card components-card"><div class="dashboard-head"><strong>组件状态 <span :class="['health-chip',{bad:!allComponentsHealthy}]">● {{allComponentsHealthy?'全部正常':'存在异常'}}</span></strong><button class="more-link" @click="go('/operations/tasks')">更多组件状态 ›</button></div><div class="component-grid"><article v-for="c in componentCards" :key="c.type" class="component-item"><div class="component-top"><div><strong>{{c.name}}</strong><span>{{c.engine}}</span></div><em :class="{bad:c.failed>0}">● {{c.failed>0?'异常':'正常'}}</em></div><div class="component-stats"><div><b>{{c.running}}</b><span>运行中</span></div><div><b>{{c.failed}}</b><span>失败</span></div><div><b>{{c.total}}</b><span>总任务</span></div></div></article></div></section>
    <section class="dashboard-card resource-card"><div class="dashboard-head"><strong>资源使用情况</strong><span class="monitor-state live">● 10 秒自动刷新</span></div><div v-if="systemMetrics" class="resource-metrics"><div class="resource-row"><div class="resource-label"><span>CPU</span><b>{{systemMetrics.cpuUsage.toFixed(1)}}%</b></div><div class="resource-track"><i class="cpu" :style="{width:`${systemMetrics.cpuUsage}%`}"></i></div><small>系统 CPU 使用率</small></div><div class="resource-row"><div class="resource-label"><span>内存</span><b>{{systemMetrics.memoryUsage.toFixed(1)}}%</b></div><div class="resource-track"><i class="memory" :style="{width:`${systemMetrics.memoryUsage}%`}"></i></div><small>{{formatBytes(systemMetrics.usedMemoryBytes)}} / {{formatBytes(systemMetrics.totalMemoryBytes)}}</small></div><div class="resource-row"><div class="resource-label"><span>磁盘</span><b>{{systemMetrics.diskUsage.toFixed(1)}}%</b></div><div class="resource-track"><i class="disk" :style="{width:`${systemMetrics.diskUsage}%`}"></i></div><small>{{formatBytes(systemMetrics.usedDiskBytes)}} / {{formatBytes(systemMetrics.totalDiskBytes)}}</small></div></div><div v-else class="resource-empty"><div class="resource-icon">⌁</div><strong>监控数据暂不可用</strong><span>无法读取当前服务器资源指标。</span></div></section>
  </div>

</template>

<div v-else-if="mode==='tasks'" class="ds-card task-card"><div class="task-toolbar"><div class="task-types"><button v-for="x in [{k:'ALL',n:'全部任务'},{k:'OFFLINE',n:'离线集成'},{k:'REALTIME',n:'实时集成'},{k:'DEVELOPMENT',n:'数据开发'}]" :key="x.k" :class="{active:taskType===x.k}" @click="taskType=x.k">{{x.n}}</button></div><el-input v-model="keyword" clearable placeholder="搜索任务名称" style="width:240px"/></div><div v-if="!filteredTasks.length" class="ds-empty"><div><div class="ds-empty__title">暂无任务</div></div></div><table v-else class="ds-table task-table"><thead><tr><th>任务名称</th><th>任务类型</th><th>执行引擎</th><th>生产状态</th><th>运行状态</th><th>最近开始</th><th>最近结束</th><th class="op-col">操作</th></tr></thead><tbody><tr v-for="r in filteredTasks" :key="`${r.type}-${r.id}`"><td><div class="task-name">{{r.name}}</div><small>{{r.owner||'platform'}}</small></td><td>{{typeLabel(r.type)}}</td><td>{{r.engine}}</td><td><span class="lifecycle" :class="String(r.lifecycleStatus).toLowerCase()">{{lifecycleLabel(r.lifecycleStatus)}}</span></td><td><StatusBadge :status="r.runtimeStatus" :label="statusLabel(r.runtimeStatus)"/></td><td>{{fmt(r.lastStartedAt)}}</td><td>{{fmt(r.lastFinishedAt)}}</td><td class="task-actions"><el-button link type="primary" @click="showDetail(r)">详情</el-button><el-button link type="primary" :loading="isBusy('start',r)" :disabled="!r.canStart" @click="taskAction('start',r)">启动</el-button><el-button link type="primary" :loading="isBusy('rerun',r)" :disabled="!r.canRerun" @click="taskAction('rerun',r)">重跑</el-button><el-button link type="danger" :loading="isBusy('kill',r)" :disabled="!r.canKill" @click="taskAction('kill',r)">杀死</el-button><el-button link type="primary" :disabled="!r.lastExecutionId" @click="showLog(r)">日志</el-button></td></tr></tbody></table></div>

<div v-else-if="mode==='instances'" class="ds-card"><div v-if="!instances.length" class="ds-empty"><div><div class="ds-empty__title">暂无运行实例</div></div></div><table v-else class="ds-table"><thead><tr><th>名称</th><th>类型</th><th>状态</th><th>开始时间</th><th>结束时间</th><th>操作</th></tr></thead><tbody><tr v-for="r in instances" :key="`${r.type}-${r.id}`"><td class="ds-resource">{{r.name}}</td><td>{{typeLabel(r.type)}}</td><td><StatusBadge :status="r.status" :label="statusLabel(r.status)"/></td><td>{{fmt(r.startedAt||r.createdAt)}}</td><td>{{fmt(r.finishedAt)}}</td><td><el-button link type="primary" @click="instanceLog(r)">日志</el-button><el-button v-if="/RUNNING|START/i.test(r.status)" link type="danger" @click="stopInstance(r)">杀死</el-button></td></tr></tbody></table></div>
<div v-else-if="mode==='failures'" class="ds-card"><div v-if="!failures.length" class="ds-empty"><div><div class="ds-empty__title">当前无失败任务</div></div></div><table v-else class="ds-table"><thead><tr><th>任务</th><th>类型</th><th>引擎</th><th>状态</th><th>错误</th><th>开始时间</th></tr></thead><tbody><tr v-for="r in failures" :key="`${r.type}-${r.id}`"><td class="ds-resource">{{r.name}}</td><td>{{typeLabel(r.type)}}</td><td>{{r.engine}}</td><td><StatusBadge :status="r.status" :label="statusLabel(r.status)"/></td><td class="error-cell" :title="r.errorMessage">{{r.errorMessage||'—'}}</td><td>{{fmt(r.startedAt)}}</td></tr></tbody></table></div>
<div v-else class="ds-card"><div v-if="!alerts.length" class="ds-empty"><div><div class="ds-empty__title">暂无推送历史</div><div>只有真正执行过告警推送的记录才会显示在这里。</div></div></div><table v-else class="ds-table"><thead><tr><th>推送渠道</th><th>任务</th><th>任务状态</th><th>告警内容</th><th>推送时间</th><th>推送结果</th></tr></thead><tbody><tr v-for="r in alerts" :key="`${r.resourceId}-${r.occurredAt}`"><td>{{r.alertType}} · {{r.resourceType}}</td><td class="ds-resource">{{r.name}}</td><td><StatusBadge :status="r.status" :label="statusLabel(r.status)"/></td><td>{{r.message||'—'}}</td><td>{{fmt(r.occurredAt)}}</td><td><StatusBadge :status="r.handlingState" :label="r.handlingState==='SUCCESS'?'成功':'失败'"/></td></tr></tbody></table></div>

